define(['jquery','mage/url','underscore'],function($,urlBuilder,_){'use strict';var communesCache=null;function loadCommunes(callback){if(communesCache){callback(communesCache);return;}
$.ajax({url:urlBuilder.build('rest/V1/directory/communes'),type:'GET',dataType:'json'}).done(function(data){communesCache={};_.each(data||[],function(c){var wid=c.wilaya_id||c.region_id;if(!communesCache[wid]){communesCache[wid]=[];}
communesCache[wid].push(c);});callback(communesCache);}).fail(function(){communesCache={};callback(communesCache);});}
return function(target){return target.extend({initialize:function(){this._super();var self=this;if(this.source&&typeof this.source.get==='function'){this.source.on('shippingAddress.region_id',function(regionId){self.onWilayaChange(regionId);});}
return this;},onWilayaChange:function(regionId){if(!regionId){return;}
loadCommunes(function(grouped){var communes=grouped[regionId]||[],options=[{value:'',label:'S\u00e9lectionnez une commune'}];_.each(communes,function(c){options.push({value:c.name||c.id,label:c.name||c.id});});$(document).trigger('commune:updated',[options]);});}});};});